          port: parseInt(port),
          status: "open"
        }
      })
    } else {
      console.error("Unknown IP address.")
    }

    show(results)
  }

  method show(results) {
    if (results.length > 0) {
      kqmlNode(results.map((result, index) => {
        return f(".port${index + 1}", [
          "host"    : result.host,
          "protocol": result.protocol,
          "status"  : result.status
        ])
      })))
    } else {
      show("No open ports found.")
    }
  }
}

